-- Allineamento dati tecnici: batteria 3 giorni e precisione Wi-Fi ~15 m sono attribuiti al dispositivo del servizio eCura Premium.
-- Rimosse le cifre non verificate per gli altri piani.
UPDATE blog_articles SET content = replace(content, 'La batteria dura <strong>oltre 48 ore</strong> con GPS attivo e monitoraggio continuo. La ricarica', 'Sul dispositivo medico del servizio eCura Premium la durata della batteria dichiarata è di <strong>3 giorni</strong>. La ricarica'), updated_at = datetime('now') WHERE slug = 'caregiver-distanza-genitori-anziani-estero' AND instr(content, 'La batteria dura <strong>oltre 48 ore</strong> con GPS attivo e monitoraggio continuo. La ricarica') > 0;
UPDATE blog_articles SET content = replace(content, 'L''autonomia dei dispositivi eCura è di 24–72 ore a seconda del modello e dell''intensità d''uso.', 'Sul dispositivo medico del servizio eCura Premium la durata della batteria dichiarata è di 3 giorni.'), updated_at = datetime('now') WHERE slug = 'teleassistenza-anziani-come-funziona-costi' AND instr(content, 'L''autonomia dei dispositivi eCura è di 24–72 ore a seconda del modello e dell''intensità d''uso.') > 0;
UPDATE blog_articles SET content = replace(content, 'Wi-Fi dell''abitazione per l''area indoor (precisione 2–5 m, senza hardware aggiuntivo)', 'Wi-Fi dell''abitazione per l''area indoor (senza hardware aggiuntivo; sul dispositivo medico del servizio eCura Premium la precisione Wi-Fi dichiarata è di circa 15 m)'), updated_at = datetime('now') WHERE slug = 'gps-anziani-indoor-come-funziona' AND instr(content, 'Wi-Fi dell''abitazione per l''area indoor (precisione 2–5 m, senza hardware aggiuntivo)') > 0;
UPDATE blog_articles SET content = replace(content, 'Con il router di casa già presente, eCura può raggiungere una precisione di 2–5 metri — sufficiente a distinguere l''area dell''appartamento in cui si trova l''assistito (soggiorno vs cucina vs bagno in appartamenti standard).', 'Con il router di casa già presente, eCura può stimare in quale area dell''abitazione si trova l''assistito. Sul dispositivo medico del servizio eCura Premium la precisione Wi-Fi dichiarata è di circa 15 m; per distinguere le singole stanze servono i beacon BLE.'), updated_at = datetime('now') WHERE slug = 'gps-anziani-indoor-come-funziona' AND instr(content, 'Con il router di casa già presente, eCura può raggiungere una precisione di 2–5 metri — sufficiente a distinguere l''area dell''appartamento in cui si trova l''assistito (soggiorno vs cucina vs bagno in appartamenti standard).') > 0;
UPDATE blog_articles SET content = replace(content, 'Precisione 2–5 m, sufficiente per identificare l''area della casa.', 'Precisione Wi-Fi dichiarata sul dispositivo medico del servizio eCura Premium: circa 15 m.'), updated_at = datetime('now') WHERE slug = 'gps-anziani-indoor-come-funziona' AND instr(content, 'Precisione 2–5 m, sufficiente per identificare l''area della casa.') > 0;
UPDATE blog_articles SET content = replace(content, 'localizzazione indoor per area (2–5 m), senza costi', 'localizzazione indoor per area (Wi-Fi), senza costi'), updated_at = datetime('now') WHERE slug = 'gps-anziani-indoor-come-funziona' AND instr(content, 'localizzazione indoor per area (2–5 m), senza costi') > 0;
